"use client";

import { useEffect, useId, useRef, useState } from "react";
import * as DropdownMenu from "@radix-ui/react-dropdown-menu";
import { AnimatePresence, LayoutGroup, motion, useReducedMotion } from "motion/react";
import { ArrowDownUp, ArrowLeftRight, Check, ChevronDown } from "lucide-react";
import { motionTokens } from "@/lib/motion-tokens";
import styles from "./token-swap.module.css";

export interface SwapToken {
  /** Ticker, such as "ORB". Also the token's id. */
  symbol: string;
  /** Full name, shown in the token menu. */
  name: string;
  /** Price in US dollars. Rates between tokens derive from it. */
  price: number;
  /** Balance of the pretend wallet. */
  balance: number;
  /** Categorical tone of the token mark. */
  tone?: "teal" | "sky" | "orchid" | "violet" | "rose" | "amber" | "green";
}

export interface SwapQuote {
  /** Symbol of the token paid. */
  pay: string;
  /** Symbol of the token received. */
  receive: string;
  /** Amount paid, in the pay token. */
  amount: number;
  /** Amount received after the fee, in the receive token. */
  received: number;
}

export interface TokenSwapProps {
  /** Tokens offered in both pickers. Defaults to five made-up tokens. */
  tokens?: SwapToken[];
  /** Symbol of the token paid at the start. */
  defaultPay?: string;
  /** Symbol of the token received at the start. */
  defaultReceive?: string;
  /** Amount to pay, as typed. Pass it with `onAmountChange` to control the field. */
  amount?: string;
  /** Starting amount when uncontrolled. */
  defaultAmount?: string;
  /** Called with the cleaned text of the pay field whenever it changes. */
  onAmountChange?: (amount: string) => void;
  /** Share of the paid amount kept as a fee. Defaults to 0.3%. */
  feeRate?: number;
  /** Runs when the person confirms. The card shows its pending state until the returned promise settles; without it, a short delay stands in. */
  onSwap?: (quote: SwapQuote) => void | Promise<void>;
  /** Extra class for the card. */
  className?: string;
  /** Render the token menus inside this element and keep them within it (used by the demo stage). */
  container?: HTMLElement | null;
}

/** Made-up tokens with made-up prices. Nothing here maps to a real asset. */
export const sampleTokens: SwapToken[] = [
  { symbol: "ORB", name: "Orbit", price: 186.4, balance: 3.82, tone: "violet" },
  { symbol: "USDX", name: "Dollar X", price: 1, balance: 4210.55, tone: "sky" },
  { symbol: "LIME", name: "Lime", price: 2.418, balance: 1250, tone: "green" },
  { symbol: "KELP", name: "Kelp", price: 14.06, balance: 61.5, tone: "teal" },
  { symbol: "NOVA", name: "Nova", price: 0.0842, balance: 92400, tone: "amber" },
];

const SLIPPAGE = 0.005;
const NETWORK_FEE = 0.42;
const format = (value: number) => new Intl.NumberFormat("en-US", { maximumFractionDigits: value >= 1000 ? 2 : value >= 1 ? 4 : 6 }).format(value);
const dollars = (value: number) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(value);
/** Plain digits for the input: no grouping, and no more decimals than the size of the number deserves. */
const typed = (value: number) => String(Number(value.toFixed(value >= 1000 ? 2 : value >= 1 ? 4 : 6)));
const clean = (raw: string) => {
  const [whole = "", ...decimals] = raw.replace(/,/g, ".").replace(/[^\d.]/g, "").split(".");
  return (decimals.length ? `${whole}.${decimals.join("")}` : whole).slice(0, 14);
};

function Mark({ token }: { token: SwapToken }) {
  return <span className={styles.mark} data-tone={token.tone ?? "sky"} aria-hidden="true">{token.symbol.slice(0, 1)}</span>;
}

function TokenPicker({ label, token, tokens, balances, onPick, container }: { label: string; token: SwapToken; tokens: SwapToken[]; balances: Record<string, number>; onPick: (symbol: string) => void; container?: HTMLElement | null }) {
  return (
    <DropdownMenu.Root>
      <DropdownMenu.Trigger asChild>
        <button type="button" className={styles.token} aria-label={`${label}: ${token.name}. Change token`}>
          <Mark token={token} /><span>{token.symbol}</span><ChevronDown className={styles.chevron} size={14} aria-hidden="true" />
        </button>
      </DropdownMenu.Trigger>
      <DropdownMenu.Portal container={container ?? undefined}>
        <DropdownMenu.Content className={styles.menu} align="end" sideOffset={8} collisionPadding={12} collisionBoundary={container ?? undefined} loop>
          <DropdownMenu.Label className={styles.menuLabel}>Select a token</DropdownMenu.Label>
          <DropdownMenu.RadioGroup value={token.symbol} onValueChange={onPick}>
            {tokens.map(option => (
              <DropdownMenu.RadioItem key={option.symbol} value={option.symbol} className={styles.option}>
                <Mark token={option} />
                <span className={styles.optionText}><span className={styles.optionSymbol}>{option.symbol}</span><span className={styles.optionName}>{option.name}</span></span>
                <span className={styles.optionBalance}>{format(balances[option.symbol] ?? 0)}</span>
                <span className={styles.optionCheck}><DropdownMenu.ItemIndicator><Check size={14} aria-hidden="true" /></DropdownMenu.ItemIndicator></span>
              </DropdownMenu.RadioItem>
            ))}
          </DropdownMenu.RadioGroup>
        </DropdownMenu.Content>
      </DropdownMenu.Portal>
    </DropdownMenu.Root>
  );
}

type Phase = "idle" | "pending" | "done";

/** Swap card with play money: two amount fields with token pickers, a flip button that makes the two fields trade places, live rate and fee rows, and a pending then confirmed state. */
export function TokenSwap({ tokens = sampleTokens, defaultPay, defaultReceive, amount, defaultAmount = "1.5", onAmountChange, feeRate = 0.003, onSwap, className, container }: TokenSwapProps) {
  const reduceMotion = useReducedMotion();
  const uid = useId();
  // Each field keeps its identity when the pair flips, so the two cards visibly trade places.
  const [sides, setSides] = useState<{ key: string; symbol: string }[]>(() => [{ key: "a", symbol: defaultPay ?? tokens[0]?.symbol ?? "" }, { key: "b", symbol: defaultReceive ?? tokens[1]?.symbol ?? "" }]);
  const [internal, setInternal] = useState(defaultAmount);
  const [balances, setBalances] = useState<Record<string, number>>(() => Object.fromEntries(tokens.map(token => [token.symbol, token.balance])));
  const [flips, setFlips] = useState(0);
  const [inverted, setInverted] = useState(false);
  const [phase, setPhase] = useState<Phase>("idle");
  const [receipt, setReceipt] = useState<SwapQuote | null>(null);
  const [failed, setFailed] = useState(false);
  const alive = useRef(true);
  // Focus follows the flow: the card holds it while the form is inert, the receipt's button takes it when the swap lands,
  // the amount field gets it back on "New swap", and the confirm button after a failed swap.
  const cardRef = useRef<HTMLDivElement>(null);
  const againRef = useRef<HTMLButtonElement>(null);
  const confirmRef = useRef<HTMLButtonElement>(null);
  const focusNext = useRef<"again" | "amount" | "confirm" | null>(null);
  useEffect(() => {
    const target = focusNext.current;
    if (!target) return;
    focusNext.current = null;
    const node = target === "again" ? againRef.current : target === "confirm" ? confirmRef.current : cardRef.current?.querySelector<HTMLInputElement>("input:not([readonly])");
    node?.focus({ preventScroll: true });
  }, [phase]);
  useEffect(() => { alive.current = true; return () => { alive.current = false; }; }, []);

  const find = (symbol: string | undefined) => tokens.find(token => token.symbol === symbol) ?? tokens[0];
  const pay = find(sides[0]?.symbol), receive = find(sides[1]?.symbol);
  if (!pay || !receive) return null;

  const text = amount ?? internal;
  const value = Number(text) || 0;
  const rate = pay.price / receive.price;
  const fee = value * feeRate;
  const received = (value - fee) * rate;
  const balance = balances[pay.symbol] ?? 0;
  const short = value > balance;
  const ready = value > 0 && !short && phase === "idle";

  const setAmount = (next: string) => { if (amount === undefined) setInternal(next); onAmountChange?.(next); };
  const flip = () => {
    setSides(([first, second]) => (first && second ? [second, first] : []));
    setFlips(count => count + 1);
    if (received > 0) setAmount(typed(received));
  };
  const pick = (index: number, symbol: string) => {
    // Choosing the token that already sits on the other side is a flip.
    if (sides[1 - index]?.symbol === symbol) { flip(); return; }
    setSides(current => current.map((side, at) => (at === index ? { ...side, symbol } : side)));
  };
  const confirm = async () => {
    if (!ready) return;
    const quote: SwapQuote = { pay: pay.symbol, receive: receive.symbol, amount: value, received };
    // The form turns inert while pending; keep focus on the card (not <body>) if it was inside the form.
    if (cardRef.current?.contains(document.activeElement)) cardRef.current.focus({ preventScroll: true });
    setFailed(false);
    setPhase("pending");
    try { await (onSwap?.(quote) ?? new Promise<void>(resolve => window.setTimeout(resolve, 1700))); } catch { if (alive.current) { focusNext.current = "confirm"; setFailed(true); setPhase("idle"); } return; }
    if (!alive.current) return;
    focusNext.current = "again";
    setBalances(current => ({ ...current, [quote.pay]: (current[quote.pay] ?? 0) - quote.amount, [quote.receive]: (current[quote.receive] ?? 0) + quote.received }));
    setReceipt(quote);
    setPhase("done");
  };
  const reset = () => { focusNext.current = "amount"; setPhase("idle"); setReceipt(null); setAmount(""); };

  const swap = reduceMotion ? { duration: 0 } : { type: "spring" as const, visualDuration: 0.45, bounce: 0.18 };
  const cta = phase === "pending" ? "Confirming swap" : value <= 0 ? "Enter an amount" : short ? `Not enough ${pay.symbol}` : `Swap ${pay.symbol} for ${receive.symbol}`;
  const [base, quote] = inverted ? [receive, pay] : [pay, receive];

  return (
    <div ref={cardRef} tabIndex={-1} className={[styles.swap, className].filter(Boolean).join(" ")} data-phase={phase}>
      <form className={styles.form} inert={phase !== "idle"} onSubmit={event => { event.preventDefault(); void confirm(); }}>
        <header className={styles.header}>
          <h2 className={styles.title}>Swap</h2>
          <span className={styles.badge}>Play money</span>
        </header>

        <LayoutGroup id={uid}>
          <div className={styles.pair}>
            {sides.map((side, index) => {
              const token = index === 0 ? pay : receive;
              const paying = index === 0;
              const shown = paying ? text : received > 0 ? typed(received) : "";
              const worth = (paying ? value : received) * token.price;
              return (
                <motion.div key={side.key} layout="position" className={styles.field} data-short={paying && short ? "true" : undefined} style={{ zIndex: paying ? 2 : 1 }} transition={swap}>
                  {/* The card that moves up passes over the other one: it swells a little while its partner dips. */}
                  <motion.div key={flips} className={styles.fieldInner} initial={flips === 0 || reduceMotion ? false : { scale: paying ? 1.045 : 0.94 }} animate={{ scale: 1 }} transition={swap}>
                  <div className={styles.fieldTop}>
                    <label htmlFor={`${uid}-${side.key}`}>{paying ? "You pay" : "You receive"}</label>
                    <span className={styles.balance}>
                      Balance {format(balances[token.symbol] ?? 0)}
                      {paying ? <button type="button" className={styles.max} onClick={() => setAmount(typed(balance))}>Max</button> : null}
                    </span>
                  </div>
                  <div className={styles.fieldMain}>
                    <input id={`${uid}-${side.key}`} className={styles.amount} value={shown} readOnly={!paying} tabIndex={paying ? 0 : -1} inputMode="decimal" autoComplete="off" placeholder="0" aria-invalid={paying && short ? true : undefined} aria-describedby={`${uid}-${side.key}-worth`} onChange={event => { if (paying) setAmount(clean(event.target.value)); }} />
                    <TokenPicker label={paying ? "Pay with" : "Receive"} token={token} tokens={tokens} balances={balances} onPick={symbol => pick(index, symbol)} container={container} />
                  </div>
                  <p id={`${uid}-${side.key}-worth`} className={styles.worth}>{paying && short ? `You only have ${format(balance)} ${token.symbol}` : worth > 0 ? `About ${dollars(worth)}` : "\u00a0"}</p>
                </motion.div>
                </motion.div>
              );
            })}
            <motion.button type="button" className={styles.flip} aria-label={`Flip: pay ${receive.symbol}, receive ${pay.symbol}`} onClick={flip} whileTap={reduceMotion ? undefined : { scale: 0.9 }} transition={motionTokens.spring.snappy}>
              <motion.span className={styles.flipIcon} initial={false} animate={{ rotate: reduceMotion ? 0 : flips * 180 }} transition={swap}><ArrowDownUp size={16} aria-hidden="true" /></motion.span>
            </motion.button>
          </div>
        </LayoutGroup>

        <dl className={styles.rows}>
          <div className={styles.row}>
            <dt>Rate</dt>
            <dd>
              <button type="button" className={styles.rate} aria-label="Show the rate the other way round" onClick={() => setInverted(current => !current)}>
                <AnimatePresence mode="popLayout" initial={false}>
                  <motion.span key={`${base.symbol}-${quote.symbol}`} initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -8 }} transition={{ duration: motionTokens.duration.fast, ease: motionTokens.ease.standard }}>
                    1 {base.symbol} = {format(base.price / quote.price)} {quote.symbol}
                  </motion.span>
                </AnimatePresence>
                <ArrowLeftRight size={12} aria-hidden="true" />
              </button>
            </dd>
          </div>
          <div className={styles.row}><dt>Fee ({(feeRate * 100).toFixed(1)}%)</dt><dd>{value > 0 ? `${format(fee)} ${pay.symbol}` : "—"}</dd></div>
          <div className={styles.row}><dt>Network cost</dt><dd>{dollars(NETWORK_FEE)}</dd></div>
          <div className={styles.row}><dt>Minimum received</dt><dd>{received > 0 ? `${format(received * (1 - SLIPPAGE))} ${receive.symbol}` : "—"}</dd></div>
        </dl>

        <button ref={confirmRef} type="submit" className={styles.confirm} disabled={!ready && phase === "idle"} data-pending={phase === "pending" ? "true" : undefined}>
          <AnimatePresence mode="popLayout" initial={false}>
            <motion.span key={cta} className={styles.confirmLabel} initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -10 }} transition={{ duration: motionTokens.duration.fast, ease: motionTokens.ease.standard }}>
              {phase === "pending" ? <span className={styles.spinner} aria-hidden="true" /> : null}{cta}
            </motion.span>
          </AnimatePresence>
        </button>
      </form>
      {/* Outside the form: an inert form drops out of the accessibility tree, and this line must still be announced. */}
      <p className={styles.notice} role="status" data-quiet={failed && phase === "idle" ? undefined : ""}>{phase === "pending" ? "Confirming the swap…" : failed ? "The swap did not go through. Nothing was charged; try again." : ""}</p>

      <AnimatePresence>
        {phase === "done" && receipt ? (
          <motion.div key="receipt" className={styles.receipt} role="status" initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.96 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, transition: { duration: motionTokens.duration.instant } }} transition={reduceMotion ? { duration: motionTokens.duration.fast } : motionTokens.spring.gentle}>
            <svg className={styles.tick} viewBox="0 0 56 56" aria-hidden="true">
              <motion.circle cx="28" cy="28" r="26" initial={reduceMotion ? false : { scale: 0.4, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={{ type: "spring", visualDuration: 0.4, bounce: 0.3 }} />
              <motion.path d="M18 28.5l7 7 13-14" initial={reduceMotion ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 0.32, ease: motionTokens.ease.standard, delay: reduceMotion ? 0 : 0.2 }} />
            </svg>
            <p className={styles.receiptTitle}>Swap confirmed</p>
            <p className={styles.receiptLine}>{format(receipt.amount)} {receipt.pay} <ArrowLeftRight size={13} aria-hidden="true" /> {format(receipt.received)} {receipt.receive}</p>
            <p className={styles.receiptNote}>Balances updated. This is play money: nothing left this page.</p>
            <button ref={againRef} type="button" className={styles.again} onClick={reset}>New swap</button>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

/** Ready preview: the swap card centered on a quiet stage. */
export function TokenSwapPreview({ container }: { container?: HTMLElement | null } = {}) {
  return (
    <section className={styles.preview} aria-label="Token swap">
      <TokenSwap container={container} />
    </section>
  );
}

export default TokenSwapPreview;

.swap { position: relative; width: min(26rem, 100%); overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-surface); background: var(--surface); box-shadow: var(--shadow-raised); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); }
.swap *, .swap *::before, .swap *::after { box-sizing: border-box; }
.form { display: grid; gap: var(--space-3); padding: var(--space-4); transition: opacity var(--duration-standard) var(--ease-standard); }
.swap[data-phase="done"] .form { opacity: 0; }

.header { display: flex; align-items: center; justify-content: space-between; padding: var(--space-1) var(--space-2) 0; }
.title { margin: 0; font-family: var(--font-display); font-size: var(--text-lg); font-weight: 500; letter-spacing: var(--tracking-display); }
.badge { padding: 3px var(--space-2); border-radius: var(--radius-pill); background: var(--surface-muted); color: var(--text-secondary); font-size: var(--text-xs); font-weight: 500; }

/* The two fields are one pair with the flip button pinned over the seam between them. */
.pair { position: relative; display: grid; gap: 6px; }
.field { position: relative; }
.fieldInner { display: grid; gap: var(--space-1); padding: var(--space-3) var(--space-4); border: 1px solid transparent; border-radius: var(--radius-panel); background: var(--surface-muted); transition: border-color var(--duration-fast) var(--ease-standard); }
.field:focus-within .fieldInner { border-color: var(--border-strong); }
.field[data-short] .fieldInner { border-color: var(--danger); }
.fieldTop { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); color: var(--text-secondary); font-size: var(--text-xs); }
.fieldTop label { font-weight: 500; }
.balance { display: inline-flex; align-items: center; gap: var(--space-2); color: var(--text-muted); font-variant-numeric: tabular-nums; white-space: nowrap; }
.max { height: 22px; padding: 0 var(--space-2); border: 0; border-radius: var(--radius-pill); background: var(--accent-subtle); color: var(--accent-strong); font: inherit; font-weight: 600; cursor: pointer; transition: transform var(--duration-fast) var(--ease-standard); }
.max:active { transform: scale(.94); }
.fieldMain { display: flex; align-items: center; gap: var(--space-2); }
.amount { width: 100%; min-width: 0; flex: 1 1 auto; padding: 0; border: 0; background: transparent; color: var(--foreground); font-family: var(--font-display); font-size: var(--text-3xl); font-weight: 500; font-variant-numeric: tabular-nums; letter-spacing: var(--tracking-display); line-height: 1.2; text-overflow: ellipsis; outline: none; }
.amount::placeholder { color: var(--text-muted); opacity: .6; }
.amount:read-only { cursor: default; }
.worth { min-height: 1.4em; margin: 0; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; line-height: 1.4; }
.field[data-short] .worth { color: var(--danger); }

.token { display: inline-flex; height: 38px; flex: none; align-items: center; gap: var(--space-2); padding: 0 var(--space-2) 0 5px; border: 1px solid var(--border); border-radius: var(--radius-pill); background: var(--surface-raised); box-shadow: var(--shadow-resting); color: var(--foreground); font: inherit; font-size: var(--text-sm); font-weight: 600; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-fast) var(--ease-standard), transform var(--duration-fast) var(--ease-standard); }
.token:hover { background: var(--surface); }
.token:active { transform: scale(.97); }
.chevron { color: var(--text-muted); transition: transform var(--duration-standard) var(--ease-standard); }
.token[data-state="open"] .chevron { transform: rotate(180deg); }
.mark { --tone: var(--tone-sky); display: grid; width: 28px; height: 28px; flex: none; place-items: center; border-radius: var(--radius-pill); background: color-mix(in oklab, var(--tone) 20%, transparent); color: var(--tone); font-family: var(--font-display); font-size: var(--text-sm); font-weight: 600; }
.mark[data-tone="teal"] { --tone: var(--tone-teal); }
.mark[data-tone="orchid"] { --tone: var(--tone-orchid); }
.mark[data-tone="violet"] { --tone: var(--tone-violet); }
.mark[data-tone="rose"] { --tone: var(--tone-rose); }
.mark[data-tone="amber"] { --tone: var(--tone-amber); }
.mark[data-tone="green"] { --tone: var(--tone-green); }

.flip { position: absolute; top: 50%; left: 50%; z-index: 3; display: grid; width: 40px; height: 40px; margin: -20px 0 0 -20px; place-items: center; padding: 0; border: 4px solid var(--surface); border-radius: var(--radius-pill); background: var(--accent); color: var(--accent-foreground); cursor: pointer; -webkit-tap-highlight-color: transparent; }
.flipIcon { display: grid; place-items: center; }

.rows { display: grid; gap: var(--space-2); margin: 0; padding: var(--space-2) var(--space-2) var(--space-1); }
.row { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); font-size: var(--text-sm); }
.row dt { color: var(--text-muted); }
.row dd { margin: 0; overflow: hidden; color: var(--text-secondary); font-variant-numeric: tabular-nums; text-overflow: ellipsis; white-space: nowrap; }
.rate { display: inline-flex; align-items: center; gap: 6px; overflow: hidden; padding: 0; border: 0; border-radius: var(--radius-pill); background: transparent; color: var(--foreground); font: inherit; font-variant-numeric: tabular-nums; cursor: pointer; }
.rate span { display: inline-block; }
.rate svg { flex: none; color: var(--text-muted); }

.confirm { position: relative; display: grid; height: var(--control-height-lg); place-items: center; overflow: hidden; padding: 0 var(--space-4); border: 0; border-radius: var(--radius-panel); background: var(--accent); color: var(--accent-foreground); font: inherit; font-size: var(--text-base); font-weight: 600; cursor: pointer; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-standard) var(--ease-standard), color var(--duration-standard) var(--ease-standard), transform var(--duration-fast) var(--ease-standard); }
.confirm:active:not(:disabled) { transform: scale(.985); }
.confirm:disabled { background: var(--surface-muted); color: var(--text-muted); cursor: default; }
.confirmLabel { display: inline-flex; align-items: center; gap: var(--space-2); white-space: nowrap; }
.spinner { width: 16px; height: 16px; border: 2px solid currentColor; border-right-color: transparent; border-radius: var(--radius-pill); animation: turn .7s linear infinite; }
@keyframes turn { to { transform: rotate(360deg); } }

/* The confirmation covers the form instead of replacing it, so the card never changes size. */
.receipt { position: absolute; inset: 0; z-index: 4; display: grid; align-content: center; justify-items: center; gap: var(--space-2); padding: var(--space-6); background: var(--surface); text-align: center; }
.tick { width: 56px; height: 56px; margin-bottom: var(--space-2); overflow: visible; }
.tick circle { fill: var(--accent); transform-box: fill-box; transform-origin: center; }
.tick path { fill: none; stroke: var(--accent-foreground); stroke-width: 3.5; stroke-linecap: round; stroke-linejoin: round; }
.receiptTitle { margin: 0; font-family: var(--font-display); font-size: var(--text-xl); font-weight: 500; letter-spacing: var(--tracking-display); }
.receiptLine { display: inline-flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: var(--space-2); margin: 0; font-size: var(--text-base); font-variant-numeric: tabular-nums; }
.receiptNote { max-width: 28ch; margin: 0; color: var(--text-muted); font-size: var(--text-sm); line-height: var(--leading-body); text-wrap: balance; }
.again { height: var(--control-height-md); margin-top: var(--space-3); padding: 0 var(--space-5); border: 1px solid var(--border); border-radius: var(--radius-pill); background: var(--surface-raised); color: var(--foreground); font: inherit; font-size: var(--text-sm); font-weight: 500; cursor: pointer; transition: background-color var(--duration-fast) var(--ease-standard); }
.again:hover { background: var(--surface-muted); }

/* The token menu renders in a portal, outside the card, so it sets its own type and colors. */
.menu { z-index: 50; min-width: 15rem; padding: var(--space-1); border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface-raised); box-shadow: var(--shadow-floating); color: var(--foreground); font-family: var(--font-body); letter-spacing: var(--tracking-body); transform-origin: var(--radix-dropdown-menu-content-transform-origin); animation: menu-in var(--duration-standard) var(--ease-enter); }
.menu[data-state="closed"] { animation: menu-out var(--duration-instant) var(--ease-exit) forwards; }
@keyframes menu-in { from { opacity: 0; transform: scale(.94) translateY(-4px); } }
@keyframes menu-out { to { opacity: 0; transform: scale(.97); } }
.menuLabel { padding: var(--space-2) var(--space-2) var(--space-1); color: var(--text-muted); font-size: var(--text-xs); font-weight: 500; }
.option { display: flex; align-items: center; gap: var(--space-3); padding: var(--space-2); border-radius: calc(var(--radius-control) - 5px); font-size: var(--text-sm); cursor: pointer; outline: none; user-select: none; }
.option[data-highlighted] { background: var(--surface-muted); }
.optionText { display: grid; min-width: 0; flex: 1 1 auto; }
.optionSymbol { font-weight: 600; line-height: 1.3; }
.optionName { color: var(--text-muted); font-size: var(--text-xs); line-height: 1.3; }
.optionBalance { color: var(--text-secondary); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.optionCheck { display: grid; width: 16px; flex: none; place-items: center; color: var(--accent-strong); }

.preview { display: grid; min-height: 620px; flex: 1 1 auto; place-items: center; padding: var(--space-8) var(--space-4); background: var(--background); }

@media (prefers-reduced-motion: reduce) { .form, .fieldInner, .token, .chevron, .confirm, .max { transition: none; } .menu, .menu[data-state="closed"] { animation: none; } .spinner { animation-duration: 1.6s; } }
/* Status line under the form: visible only for a failed swap; otherwise it stays in the accessibility tree for announcements. */
.notice { margin: calc(var(--space-1) * -1) 0 0; padding: 0 var(--space-4) var(--space-4); color: var(--danger); font-size: var(--text-sm); line-height: var(--leading-body); text-align: center; }
.notice[data-quiet] { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
